using OpenCvSharp;
using Link360Desktop;
internal static class PoseReview {
 public static void Analyze(string file){
  using var cap=new VideoCapture(file);using var detector=new LocalWholeBodyDetector(true);using var pose=new LocalPoseDetector(true);using var pair=new Mat();using var image=new Mat();var rows=new List<(double T,bool Old,bool Guard)>();
  for(double t=0;t<Math.Min(60,cap.FrameCount/cap.Fps);t+=.5){cap.Set(VideoCaptureProperties.PosMsec,t*1000);if(!cap.Read(pair))break;using var tile=new Mat(pair,new Rect(480,0,480,270));Cv2.Resize(tile,image,new Size(320,180));var bytes=image.ToBytes(".jpg");var body=detector.Detect(bytes);bool old=false,guard=false;if(body.People.Length==1){var p=body.People[0];bool Inside((double X,double Y)? point)=>point is {} xy&&xy.X>=p.X&&xy.X<=p.X+p.Width&&xy.Y>=p.Y&&xy.Y<=p.Y+p.Height;var result=pose.Detect(bytes,p,(j,c)=>old=Inside(TorsoAnchor.Select(j,c,320,180)));guard=result.TorsoX.HasValue&&Inside((result.TorsoX.Value,result.TorsoY!.Value));}rows.Add((t,old,guard));}
  foreach(var phase in new[]{(0,15),(15,35),(35,60)}){var part=rows.Where(r=>r.T>=phase.Item1&&r.T<phase.Item2).ToArray();Console.WriteLine(System.Text.Json.JsonSerializer.Serialize(new{from=phase.Item1,to=phase.Item2,samples=part.Length,oldTorsoAccepted=part.Count(r=>r.Old),guardTorsoAccepted=part.Count(r=>r.Guard),newlyRejected=part.Count(r=>r.Old&&!r.Guard),meaning="Offline recorded-preview geometry check; not a live smoothness test or labelled pose benchmark"}));}
 }
 public static void Run(string file,double milliseconds,string output,bool gpu=true,bool nativeRoi=false,bool expandedRoi=false){
  using var cap=new VideoCapture(file);cap.Set(VideoCaptureProperties.PosMsec,milliseconds);using var pair=new Mat();if(!cap.Read(pair))throw new IOException("Cannot read test frame");using var tile=new Mat(pair,new Rect(480,0,480,270));using var image=new Mat();Cv2.Resize(tile,image,new Size(320,180));var bytes=image.ToBytes(".jpg");Console.WriteLine(System.Text.Json.JsonSerializer.Serialize(new{faces=LocalFaceDetector.Detect(bytes)}));using IBodyDetector detector=nativeRoi?new LocalBodyDetector(gpu):new LocalWholeBodyDetector(gpu);var body=detector.Detect(bytes);if(body.People.Length!=1)throw new IOException("Expected one person for pose review");using var pose=new LocalPoseDetector(gpu);var person=body.People[0];if(expandedRoi)person=person with{HipY=person.Y+person.Height*1.05,Radius=person.Height*1.15};Cv2.Rectangle(image,new Rect((int)person.X,(int)person.Y,(int)person.Width,(int)person.Height),Scalar.Yellow,1);
  var observation=pose.Detect(bytes,person,(joints,confidence)=>{foreach(int i in new[]{0,11,12,23,24}){var p=joints[i];Cv2.Circle(image,new Point(p.X,p.Y),3,Scalar.Cyan,1);Cv2.PutText(image,$"{i}",new Point(p.X+3,p.Y),HersheyFonts.HersheySimplex,.3,Scalar.Cyan);Console.WriteLine(System.Text.Json.JsonSerializer.Serialize(new{index=i,p.X,p.Y,p.Visibility,p.Presence,confidence}));}});
  Console.WriteLine(System.Text.Json.JsonSerializer.Serialize(new{person,observation}));using var enlarged=new Mat();Cv2.Resize(image,enlarged,new Size(960,540));Cv2.ImWrite(output,enlarged);
 }
}
